css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); --pivot: calc(var(--loader-size) * .3); width: var(--loader-size); height: calc(var(--loader-size) * .58); position: relative; }
.loader::before { content: ''; position: absolute; top: calc(50% - 1.5px); left: 0; width: 100%; height: 3px; background: repeating-linear-gradient(90deg, color-mix(in srgb, #000 26%, var(--accent-2)) 0 calc(var(--loader-size) * .045), transparent calc(var(--loader-size) * .045) calc(var(--loader-size) * .085)); }
.loader::after { content: ''; position: absolute; z-index: 3; top: calc(50% - var(--loader-size) * .022); left: calc(8% + var(--pivot) - var(--loader-size) * .022); width: calc(var(--loader-size) * .044); height: calc(var(--loader-size) * .044); border-radius: 50%; background: color-mix(in srgb, #000 45%, var(--accent)); }
.loader span { position: absolute; left: 8%; top: calc(50% - var(--loader-size) * .045); width: 84%; height: calc(var(--loader-size) * .09); transform-origin: var(--pivot) center; }
.loader span::before { content: ''; position: absolute; inset: 0; clip-path: polygon(0 42%, 30% 16%, 100% 44%, 100% 56%, 30% 84%, 0 58%); }
.loader span::after { content: ''; position: absolute; top: 50%; left: calc(var(--loader-size) * -.01); width: calc(var(--loader-size) * .15); height: calc(var(--loader-size) * .15); border-radius: 50%; border: calc(var(--loader-size) * .028) solid var(--accent-2); }
.loader span:nth-child(1) { animation: snip-top calc(var(--loader-speed) * 1.3) ease-in-out infinite; }
.loader span:nth-child(1)::before { background: linear-gradient(180deg, color-mix(in srgb, #fff 66%, var(--accent)), var(--accent)); }
.loader span:nth-child(1)::after { margin-top: calc(var(--loader-size) * -.155); }
.loader span:nth-child(2) { animation: snip-bottom calc(var(--loader-speed) * 1.3) ease-in-out infinite; }
.loader span:nth-child(2)::before { background: linear-gradient(180deg, var(--accent), color-mix(in srgb, #000 26%, var(--accent))); }
.loader span:nth-child(2)::after { margin-top: calc(var(--loader-size) * .005); }
@keyframes snip-top { 0%, 100% { transform: rotate(-17deg); } 50% { transform: rotate(-3deg); } }
@keyframes snip-bottom { 0%, 100% { transform: rotate(17deg); } 50% { transform: rotate(3deg); } }
